@IsTest private class AnnotatedMethodObservation {
 @IsTest static void observe() {
AtlasAction.Input a = new AtlasAction.Input(); a.value = 'alpha';
AtlasAction.Input b = new AtlasAction.Input(); b.value = 'beta';
List<AtlasAction.Output> values = AtlasAction.apply(new List<AtlasAction.Input>{a,b});
GlyphAction.Input g = new GlyphAction.Input(); g.value = 'gamma';
List<GlyphAction.Output> plain = GlyphAction.apply(new List<GlyphAction.Input>{g});
Map<String,Object> observation = new Map<String,Object>{
 'sourceApi'=>61, 'helperApi'=>67, 'route'=>'named', 'stage'=>'complete',
 'nullCount'=>AtlasAction.apply(null).size(),
 'emptyCount'=>AtlasAction.apply(new List<AtlasAction.Input>()).size(),
 'valueCount'=>values.size(), 'values'=>new List<String>{values[0].value,values[1].value},
 'plainCount'=>plain.size(), 'plainValues'=>new List<String>{plain[0].value},
 'scalar'=>AtlasAction.scalar('delta')};
String payload = JSON.serialize(observation);
System.assert(payload.length() < 800, 'Observation transport bound');
System.assert(false, 'ANNOTATED_METHOD_OBSERVATION|' + payload);
 }
}

